    return area === undefined
      ? { key: `entry-${index}`, name: '[hostId]/index', params: { hostId, ...query } }
      : {
          key: `entry-${index}`,
          name: `[hostId]/${area}/[worktreeId]`,
          params: { hostId, worktreeId: worktreeId ?? '', ...query }
        }
  })

